\begin{tikzpicture}[x=1.8cm,y=1.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{seriesBlue}{HTML}{268CFF}
\path[use as bounding box] (-1.65,-2.7) rectangle (2.75,1.85);
\draw[->,line width=.5pt] (-1.5,0)--(2.6,0) node[right] {$x$};
\draw[->,line width=.5pt] (0,-2.5)--(0,1.65) node[above] {$y$};
\foreach \v in {-1,1,2}{\draw[line width=.4pt] (\v,-.035)--(\v,.035);\node[below] at (\v,-.06) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {-2,-1,1}{\draw[line width=.4pt] (-.035,\v)--(.035,\v);\node[left] at (-.06,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\begin{scope}
\clip (-1.5,-2.5) rectangle (2.5,1.5);
\foreach \a in {-1,-.5,0,.5,1,1.5,2}{\foreach \b in {-2,-1.5,-1,-.5,0,.5,1}{\pgfmathsetmacro{\m}{\a-\b}\pgfmathsetmacro{\dx}{.1388889/sqrt(1+\m*\m)}\pgfmathsetmacro{\dy}{\m*\dx}\draw[seriesBlue,line width=.8pt] ({\a-\dx},{\b-\dy})--({\a+\dx},{\b+\dy});}}
\draw[seriesBlue,line width=.8pt,<->] plot[domain=-1.35:2.32,samples=100] (\x,{\x-1+exp(-\x)});
\draw[seriesBlue,line width=.8pt,<->] plot[domain=-1.5:2.44,samples=100] (\x,{\x-1+exp(-\x-1)});
\draw[seriesBlue,line width=.8pt,<->] plot[domain=.64:2.5,samples=100] (\x,{\x-1-exp(1-\x)});
\end{scope}
\end{tikzpicture}
